          <fieldset${describedBy}>
            <legend>${question.prompt}</legend>
            ${question.helpText ? `<p class="question-help" id="${helpId}">${question.helpText}</p>` : ""}
            <div class="choices" role="presentation">
              ${question.choices.map((choice) => Choice(question.id, choice)).join("")}
            </div>
          </fieldset>
        </div>
      `;
