334.           { id: "q3-rust", label: "Rust", correct: true },
335.           { id: "q3-python", label: "Python", correct: false },
336.           { id: "q3-julia", label: "Julia", correct: false }
337.         ]
338.       }
339.     ];
340. 
341.     function Choice(questionId, choice) {
342.       return `
343.         <div class="choice">
344.           <input type="checkbox" id="${choice.id}" name="${questionId}" value="${choice.id}">
345.           <label for="${choice.id}">${choice.label}</label>
346.         </div>
347.       `;
348.     }
349. 
350.     function QuestionCard(question, index) {
351.       const helpId = question.helpText ? `${question.id}-help` : "";
352.       const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";
353. 
354.       return `
355.         <div class="form-field">
356.           <fieldset${describedBy}>
357.             <legend>${question.prompt}</legend>
358.             ${question.helpText ? `<p class="question-help" id="${helpId}">${question.helpText}</p>` : ""}
359.             <div class="choices" role="presentation">
360.               ${question.choices.map((choice) => Choice(question.id, choice)).join("")}
361.             </div>
362.           </fieldset>
363.         </div>
364.       `;
365.     }
366. 
367.     function App() {
368.       return `
369.         <section class="quiz-shell" aria-labelledby="quiz-title">
370.           <header class="hero">
371.             <p class="eyebrow">Language fundamentals</p>
372.             <h1 id="quiz-title">Computer Languages Quiz</h1>
373.             <p class="intro">Pick every answer you think fits each question, then check your score.</p>
374.           </header>
375. 
