381.               <p class="status" id="quiz-status" aria-live="polite"></p>
382.             </div>
383. 
384.             <div class="results" id="quiz-results" aria-live="polite"></div>
385.           </form>
386.         </section>
387.       `;
388.     }
389. 
390.     function scoreQuiz(form) {
391.       return quizData.map((question) => {
392.         const checkedIds = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`)).map((input) => input.value);
393.         const correctIds = question.choices.filter((choice) => choice.correct).map((choice) => choice.id);
394.         const isExactMatch =
395.           checkedIds.length === correctIds.length &&
396.           checkedIds.every((value) => correctIds.includes(value));
397. 
398.         return {
399.           question: question.prompt,
400.           isExactMatch,
401.           selectedCount: checkedIds.length,
402.           correctCount: correctIds.length
403.         };
404.       });
405.     }
406. 
407.     const appRoot = document.getElementById("app");
408.     appRoot.innerHTML = App();
409. 
410.     const form = document.getElementById("quiz-form");
411.     const status = document.getElementById("quiz-status");
412.     const results = document.getElementById("quiz-results");
413. 
