415.       event.preventDefault();
416. 
417.       const scored = scoreQuiz(form);
418.       const correctCount = scored.filter((item) => item.isExactMatch).length;
419.       const totalCount = scored.length;
420. 
421.       status.dataset.tone = correctCount === totalCount ? "success" : "info";
422.       status.textContent = `You got ${correctCount} of ${totalCount} questions exactly right.`;
