 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <div id="app"></div>
   </main>

   <script>
     const quizData = [
       {
         id: "q1",
         prompt: "Which of these are programming languages?",
         helpText: "Select all that apply.",
         choices: [
           { id: "q1-cobol", label: "COBOL", correct: true },
           { id: "q1-haskell", label: "Haskell", correct: true },
           { id: "q1-pascal", label: "Pascal", correct: true },
           { id: "q1-photoshop", label: "Photoshop", correct: false }
         ]
       },
       {
         id: "q2",
         prompt: "Which are commonly used to build web pages or web apps?",
         choices: [
           { id: "q2-html", label: "HTML", correct: true },
           { id: "q2-css", label: "CSS", correct: true },
           { id: "q2-javascript", label: "JavaScript", correct: true },
           { id: "q2-sqlite", label: "SQLite", correct: false }
         ]
       },
       {
         id: "q3",
         prompt: "Which are statically typed languages?",
         choices: [
           { id: "q3-typescript", label: "TypeScript", correct: true },
           { id: "q3-rust", label: "Rust", correct: true },
           { id: "q3-python", label: "Python", correct: false },
           { id: "q3-julia", label: "Julia", correct: false }
         ]
       }
     ];

     function Choice(questionId, choice) {
       return `
         <div class="choice">
           <input type="checkbox" id="${choice.id}" name="${questionId}" value="${choice.id}">
           <label for="${choice.id}">${choice.label}</label>
         </div>
       `;
     }

     function QuestionCard(question, index) {
       const helpId = question.helpText ? `${question.id}-help` : "";
       const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";

       return `
         <div class="form-field">
           <fieldset${describedBy}>
             <legend>${question.prompt}</legend>
             ${question.helpText ? `<p class="question-help" id="${helpId}">${question.helpText}</p>` : ""}
             <div class="choices" role="presentation">
               ${question.choices.map((choice) => Choice(question.id, choice)).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function App() {
       return `
         <section class="quiz-shell" aria-labelledby="quiz-title">
           <header class="hero">
             <p class="eyebrow">Language fundamentals</p>
             <h1 id="quiz-title">Computer Languages Quiz</h1>
             <p class="intro">Pick every answer you think fits each question, then check your score.</p>
           </header>

           <form id="quiz-form" novalidate>
             ${quizData.map((question, index) => QuestionCard(question, index)).join("")}

             <div class="actions">
               <button type="submit">Check answers</button>
               <p class="status" id="quiz-status" aria-live="polite"></p>
             </div>

             <div class="results" id="quiz-results" aria-live="polite"></div>
           </form>
         </section>
       `;
     }

     function scoreQuiz(form) {
       return quizData.map((question) => {
         const checkedIds = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`)).map((input) => input.value);
         const correctIds = question.choices.filter((choice) => choice.correct).map((choice) => choice.id);
         const isExactMatch =
           checkedIds.length === correctIds.length &&
           checkedIds.every((value) => correctIds.includes(value));

         return {
           question: question.prompt,
           isExactMatch,
           selectedCount: checkedIds.length,
           correctCount: correctIds.length
         };
       });
     }

     const appRoot = document.getElementById("app");
     appRoot.innerHTML = App();

     const form = document.getElementById("quiz-form");
     const status = document.getElementById("quiz-status");
     const results = document.getElementById("quiz-results");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const scored = scoreQuiz(form);
       const correctCount = scored.filter((item) => item.isExactMatch).length;
       const totalCount = scored.length;

       status.dataset.tone = correctCount === totalCount ? "success" : "info";
       status.textContent = `You got ${correctCount} of ${totalCount} questions exactly right.`;

       results.innerHTML = scored.map((item, index) => {
         const outcome = item.isExactMatch ? "Correct" : "Not quite";
         return `
           <article class="result-card">
             <strong>Question ${index + 1}:</strong> ${outcome}
           </article>
         `;
       }).join("");
     });
   </script>
 </body>
 </html>

